// flutter test --no-pub tool/check_compiled_picker_pack.dart
// Requires the files generated by build_compiled_picker_pack.dart.
// ignore_for_file: invalid_use_of_visible_for_testing_member, avoid_print
// ignore_for_file: avoid_relative_lib_imports
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:fastlottie/fastlottie.dart';
import 'package:fastlottie/src/bitstream_cache.dart';
import 'package:fastlottie/src/snapshot_envelope.dart';
import 'package:flutter_test/flutter_test.dart';

import '../example/lib/tgs/compiled_pack.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  test('the installed pack graph reproduces bundled TGS pixels and keys', () {
    const path = String.fromEnvironment(
      'FASTLOTTIE_PACK_PATH',
      defaultValue:
          'example/build/ios/iphoneos/Runner.app/Frameworks/App.framework/'
          'flutter_assets/assets/texture_picker_models.flp',
    );
    final index = File('$path.json').readAsStringSync();
    final pack = CompiledModelPack.fromIndex(
      path,
      index,
      compiler: jsonDecode(index)['compiler'] as String,
    );
    expect(File(path).lengthSync(), pack.bytes);
    final reader = CompiledPackReader();
    addTearDown(reader.close);
    const borrowCoverage = bool.fromEnvironment('GEOMETRY_BORROW_COVERAGE');
    var frames = 0, borrowedDraws = 0, copiedDraws = 0;
    for (final MapEntry(key: name, value: ref) in pack.entries.entries) {
      final bytes = File('example/assets$name').readAsBytesSync();
      expect(bytes.length, ref.sourceLength);
      expect(BitstreamStore.crc31(bytes, 0, bytes.length), ref.sourceCrc);
      final payload = reader.read(ref)!;
      expect(BitstreamStore.crc31(payload, 0, payload.length), ref.payloadCrc);
      final source = FastLottieComposition.fromBytes(bytes);
      final packed = debugDecodeCompiledComposition(
        unpackCompiledSnapshot(payload),
        directPlayback: const bool.fromEnvironment(
          'FASTLOTTIE_PACK_DIRECT_PLAYBACK',
        ),
        deferPlayback: const bool.fromEnvironment(
          'FASTLOTTIE_PACK_DEFER_PLAYBACK',
        ),
      );
      expect(packed.composition.contentKey, source.contentKey, reason: name);
      expect(
        debugForkRasterScene(packed.composition).contentKey,
        source.contentKey,
        reason: name,
      );
      expect(packed.sourceBytes, decodeLottieBytes(bytes).length);
      expect(packed.composition.width, source.width);
      expect(packed.composition.height, source.height);
      expect(packed.composition.startFrame, source.startFrame);
      expect(packed.composition.endFrame, source.endFrame);
      expect(packed.composition.frameRate, source.frameRate);
      expect(packed.composition.isStatic, source.isStatic);
      expect(packed.composition.options.useSimd, source.options.useSimd);
      FastLottieSoftwareSession raster(FastLottieComposition model) =>
          FastLottieSoftwareSession(
            model,
            pixelWidth: 112,
            pixelHeight: 112,
            borrowGeometry:
                identical(model, packed.composition) && borrowCoverage,
            nativeStroke: true,
            usePreparedScene: true,
          );
      final a = raster(source), b = raster(packed.composition);
      try {
        for (final t in [0.0, .6, .25, .9, 0.0]) {
          final frame =
              source.startFrame + (source.endFrame - source.startFrame - 1) * t;
          final x = Uint8List.sublistView(a.renderFrame(frame));
          final y = Uint8List.sublistView(b.renderFrame(frame));
          for (var i = 0; i < x.length; i++) {
            if (x[i] != y[i]) fail('$name at $frame: byte $i differs');
          }
          frames++;
        }
      } finally {
        borrowedDraws += b.borrowedCoverageDraws;
        copiedDraws += b.copiedCoverageDraws;
        a.dispose();
        b.dispose();
      }
    }
    expect(pack.entries.length, 1063);
    if (borrowCoverage) {
      expect(borrowedDraws, greaterThan(0));
      expect(copiedDraws, greaterThan(0));
      print('Coverage: $borrowedDraws borrowed, $copiedDraws copied draws');
    }
    print(
      'Compiled pack: ${pack.entries.length} keys, $frames exact BGRA frames',
    );
  }, timeout: const Timeout(Duration(minutes: 4)));
}
